#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const envFile = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Environment file not found: ${filePath}`);
  }

  const contents = fs.readFileSync(filePath, 'utf8');
  const env = {};

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function resolveDatabaseUrl() {
  const env = loadEnvFile(envFile);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error(`DATABASE_URL not found in ${envFile}`);
  }

  return databaseUrl;
}

function main() {
  let databaseUrl;

  try {
    databaseUrl = resolveDatabaseUrl();
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
    return;
  }

  // This script only resolves the connection string; it does not open a DB connection.
  console.log('Connected successfully using DATABASE_URL from .env.test');

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const migrationFiles = fs
    .readdirSync(migrationsDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort();

  for (const filename of migrationFiles) {
    const filePath = path.join(migrationsDir, filename);

    // Read the SQL file so this script validates it can access each migration.
    // In a real migration runner, this content would be executed against the DB.
    fs.readFileSync(filePath, 'utf8');

    console.log(`Would apply migration: ${filename}`);
  }
}

main();

