#!/usr/bin/env node

const fs = require('fs/promises');
const path = require('path');

async function main() {
  const migrationsDir = path.join(__dirname, 'migrations');

  let entries;
  try {
    entries = await fs.readdir(migrationsDir, { withFileTypes: true });
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error('Migrations directory not found: ./migrations/');
      process.exitCode = 1;
      return;
    }
    throw error;
  }

  const sqlFiles = entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort();

  for (const filename of sqlFiles) {
    const filePath = path.join(migrationsDir, filename);

    // Read the SQL file so this script mirrors the migration discovery/apply flow.
    // The SQL is not executed; this script only logs what it would apply.
    await fs.readFile(filePath, 'utf8');

    console.log(filename);
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

