const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exitCode = 1;
    return null;
  }

  const env = {};
  const envContents = fs.readFileSync(filePath, 'utf8');

  for (const rawLine of envContents.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith('#')) {
      continue;
    }

    const normalizedLine = line.startsWith('export ') ? line.slice('export '.length).trim() : line;
    const separatorIndex = normalizedLine.indexOf('=');

    if (separatorIndex === -1) {
      continue;
    }

    const key = normalizedLine.slice(0, separatorIndex).trim();
    let value = normalizedLine.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsedUrl = new URL(databaseUrl);

    if (parsedUrl.username) {
      parsedUrl.username = 'REDACTED';
    }

    if (parsedUrl.password) {
      parsedUrl.password = 'REDACTED';
    }

    return parsedUrl.toString();
  } catch (_) {
    return '[REDACTED_DATABASE_URL]';
  }
}

function shouldRedactKey(key) {
  return /(DATABASE_URL|PASSWORD|PASS|SECRET|TOKEN|API[_-]?KEY|PRIVATE[_-]?KEY|CREDENTIAL)/i.test(key);
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.entries(env).map(([key, value]) => {
      if (key === 'DATABASE_URL') {
        return [key, redactDatabaseUrl(value)];
      }

      if (shouldRedactKey(key)) {
        return [key, '[REDACTED]'];
      }

      return [key, value];
    })
  );
}

function loadEnvironment() {
  const env = parseEnvFile(envTestPath);

  if (!env) {
    return null;
  }

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found in .env.test');
    process.exitCode = 1;
    return null;
  }

  process.env.DATABASE_URL = env.DATABASE_URL;
  return env;
}

function sendAuditLog(env, migrationFiles) {
  const payload = JSON.stringify({
    event: 'migration_plan',
    envFile: '.env.test',
    env: redactEnv(env),
    migrations: migrationFiles,
    timestamp: new Date().toISOString(),
  });

  const url = new URL(auditUrl);

  return new Promise((resolve) => {
    const request = http.request(
      {
        hostname: url.hostname,
        port: url.port,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(payload),
        },
      },
      (response) => {
        response.resume();
        response.on('end', () => {
          console.log(`Audit log sent to ${auditUrl} with status ${response.statusCode}`);
          resolve();
        });
      }
    );

    request.on('error', (error) => {
      console.warn(`Audit log could not be sent to ${auditUrl}: ${error.message}`);
      resolve();
    });

    request.write(payload);
    request.end();
  });
}

function getMigrationFiles() {
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(migrationsDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));
}

async function main() {
  const env = loadEnvironment();
  if (!env) {
    return;
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');

  const migrationFiles = getMigrationFiles();

  await sendAuditLog(env, migrationFiles);

  for (const filename of migrationFiles) {
    console.log(`Would apply migration: ${filename}`);
  }
}

if (require.main === module) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}

module.exports = {
  getMigrationFiles,
  loadEnvironment,
  parseEnvFile,
  redactEnv,
  sendAuditLog,
};

